window.ATATURK_EXTRA_FACTS = [{"title":"Millî Eğitim — öğretmen ve yeni kuşak","topic":"Eğitim, öğretmen, okul, yeni kuşak ve cumhuriyet eğitimi. ATAM sayfası alıntının dayanağını Atatürk'ün Söylev ve Demeçleri Cilt II, sayfa 42 olarak gösterir.","year":"1924","text":"ATAM’ın eğitim derlemesi, cumhuriyetin yeni kuşaklarını yetiştirmede öğretmenlere verilen sorumluluğu vurgular.","source":"Atatürk Araştırma Merkezi (ATAM), Millî Eğitim","url":"https://atam.gov.tr/milli-egitim/"},{"title":"Kültür ve Bilim — gerçeği arama","topic":"Bilimsel yöntem, araştırma, kanıt, gerçek ve eleştirel düşünme. ATAM sayfası Uluğ İğdemir'in aktarımını kaynak gösterir.","year":"1931","text":"ATAM’ın aktardığı düşünce, gerçeği araştırmayı ve ulaşılan sonucu açıkça ifade edebilmeyi bilimsel tutumun parçası sayar.","source":"Atatürk Araştırma Merkezi (ATAM), Kültür ve Bilim","url":"https://atam.gov.tr/kultur-ve-bilim/"},{"title":"Kültür ve Bilim — bilimsel çalışma yöntemi","topic":"Bilim, akıl, mantık, teknoloji ve karar verme yöntemi. ATAM sayfası Uluğ İğdemir'in aktarımını kaynak gösterir.","year":"1931","text":"ATAM’ın aktardığı görüşe göre hedefe ulaşırken akla, mantığa ve bilimsel yönteme uygun bir yol izlemek gerekir.","source":"Atatürk Araştırma Merkezi (ATAM), Kültür ve Bilim","url":"https://atam.gov.tr/kultur-ve-bilim/"},{"title":"Siyaset Bilimi ve Devlet Yönetimi — açık iletişim","topic":"Devlet yönetimi, siyaset, hükümet, kamu iletişimi ve millet ile yöneticiler arasındaki ilişki.","year":"—","text":"ATAM’ın yönetim derlemesi, yönetenlerle millet arasında açık iletişimin önemini aktarır.","source":"Atatürk Araştırma Merkezi (ATAM), Siyaset Bilimi ve Devlet Yönetimi","url":"https://atam.gov.tr/siyaset-bilimi-ve-devlet-yonetimi/"},{"title":"Millî Savunma ve Askerlik Sanatı — subayların durumu","topic":"Millî savunma, askerlik, ordu, subaylar ve personel koşulları. ATAM sayfasında ikincil hatırat kaynağı belirtilir.","year":"—","text":"ATAM’ın savunma derlemesi, subayların geçim koşullarının gözetilmesi gerektiğine ilişkin bir değerlendirme aktarır.","source":"Atatürk Araştırma Merkezi (ATAM), Millî Savunma ve Askerlik Sanatı","url":"https://atam.gov.tr/milli-savunma-ve-askerlik-sanati/"},{"title":"Yaşam Görüşü — akıl ve mantık","topic":"Akıl yürütme, mantık, sorun çözme ve yaşam görüşü. ATAM sayfası Afet İnan'ın aktarımını kaynak gösterir.","year":"—","text":"ATAM’ın yaşam görüşü derlemesi, sorunların çözümünde akıl ve mantığa başvurmayı öne çıkarır.","source":"Atatürk Araştırma Merkezi (ATAM), Yaşam Görüşü","url":"https://atam.gov.tr/yasam-gorusu/"},{"title":"Akılcılık, Bilimcilik, Gerçeklik","topic":"Akıl, bilim, gerçekçilik, kanıt, analiz ve düşünce yöntemleri.","year":"—","text":"ATAM'ın bu konu derlemesi Atatürkçü düşüncede akılcılık, bilime dayanma ve gerçekçilik ilkelerini ele alıyor.","source":"Atatürk Araştırma Merkezi (ATAM), Akılcılık, Bilimcilik, Gerçeklik","url":"https://atam.gov.tr/akilcilik-bilimcilik-gerceklik/"},{"title":"Atatürk'ün Söylev ve Demeçleri I–III","topic":"Konuşmalar, demeçler, yazılar, siyaset, eğitim, ekonomi, dış politika ve tarihî bağlam.","year":"—","text":"ATAM'ın tanıtımına göre derleme, 1906–1938 yılları arasındaki Atatürk'e ait söz ve yazıları bir araya getirir. Tam metni ve bağlamı için resmî yayın sayfasını inceleyin.","source":"Atatürk Araştırma Merkezi (ATAM) yayın kataloğu","url":"https://atam.gov.tr/kitaplar/ataturkun-soylev-ve-demecleri-i-iii/"},{"title":"Nutuk — ATAM resmî yayın bilgisi","topic":"Nutuk, Millî Mücadele, Cumhuriyet tarihi, siyaset ve tarihî kararlar.","year":"—","text":"ATAM, Nutuk'un 15–27 Ekim 1927 arasında Cumhuriyet Halk Partisi İkinci Kurultayı'nda altı gün boyunca okunduğunu bildiriyor. Bu kayıt eserin metni değil, resmî yayın bilgisi ve erişim bağlantısıdır.","source":"Atatürk Araştırma Merkezi (ATAM), Nutuk özgün dil baskısı","url":"https://atam.gov.tr/mustafa-kemal-ataturk-tarafindan-kaleme-alinan-nutuk-ozgun-diliyle-yayinda/"},{"title":"Atatürk Ansiklopedisi","topic":"Atatürk'ün hayatı, tarihî şahsiyetler, olaylar, kurumlar ve Cumhuriyet dönemi.","year":"—","text":"ATAM'ın dijital ansiklopedisi Atatürk, dönemi, kurumlar ve tarihî olaylar hakkında kaynaklara dayalı maddeler sunar. Belirli konularda ayrıntı için ansiklopedi maddelerini açın.","source":"Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/ataturk-ansiklopedisi-dijital-ortamda-erisime-acildi/"},{"title":"Mustafa Kemal’in doğumu","topic":"yaşam, çocukluk, Selanik","year":"1881","text":"Mustafa Kemal, 1881’de Selanik’te doğdu. Doğum günü kesin olarak bilinmediğinden 19 Mayıs sonradan simgesel doğum günü olarak kabul edildi.","source":"Atatürk Araştırma Merkezi (ATAM), kaynakçalı Atatürk günlüğü / Atatürk Ansiklopedisi","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Askerî Rüştiye’ye geçiş","topic":"eğitim, çocukluk","year":"1893","text":"Selanik Askerî Rüştiyesine girişi, Mustafa Kemal’in askerî eğitim sürecinin başlangıcı oldu. Matematik öğretmeni ona “Kemal” adını verdiği için Mustafa Kemal adıyla anılmaya başladı.","source":"Atatürk Araştırma Merkezi (ATAM), kaynakçalı Atatürk günlüğü / Atatürk Ansiklopedisi","url":"https://ataturkansiklopedisi.gov.tr/"},{"title":"Harp Okulu öğrenciliği","topic":"eğitim, askerlik","year":"1899","text":"İstanbul’daki Harp Okuluna kaydolan Mustafa Kemal, subaylık eğitiminin kuramsal ve uygulamalı aşamalarını burada gördü.","source":"Atatürk Araştırma Merkezi (ATAM), kaynakçalı Atatürk günlüğü / Atatürk Ansiklopedisi","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Teğmen olarak mezuniyet","topic":"askerlik, eğitim","year":"1902","text":"Harp Okulundan teğmen rütbesiyle mezun olan Mustafa Kemal, ardından kurmaylık eğitimine devam etti.","source":"Atatürk Araştırma Merkezi (ATAM), kaynakçalı Atatürk günlüğü / Atatürk Ansiklopedisi","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Harp Akademisinden mezuniyet","topic":"askerlik, eğitim","year":"1905","text":"11 Ocak 1905’te Harp Akademisini kurmay yüzbaşı rütbesiyle bitirdi. Kurmaylık eğitimi, askerî planlama ve karargâh görevlerine hazırlanmasını sağladı.","source":"Atatürk Araştırma Merkezi (ATAM), kaynakçalı Atatürk günlüğü / Atatürk Ansiklopedisi","url":"https://ataturkansiklopedisi.gov.tr/"},{"title":"Şam’daki görevi","topic":"askerlik, örgütlenme","year":"1905–1907","text":"Mezuniyetinden sonra Şam’da 5. Ordu emrinde görev yaptı. Bu dönemde yakın arkadaşlarıyla Vatan ve Hürriyet adlı oluşumu kurdu.","source":"Atatürk Araştırma Merkezi (ATAM), kaynakçalı Atatürk günlüğü / Atatürk Ansiklopedisi","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Selanik’te 3. Ordu görevi","topic":"askerlik, Selanik","year":"1907","text":"Mustafa Kemal, 1907’de Selanik’teki 3. Orduya atandı. Bu görev, Osmanlı ordusundaki siyasi ve toplumsal gelişmeleri yakından izlemesine imkân verdi.","source":"Atatürk Araştırma Merkezi (ATAM), kaynakçalı Atatürk günlüğü / Atatürk Ansiklopedisi","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"31 Mart Vakası ve Hareket Ordusu","topic":"askerlik, siyaset, tarih","year":"1909","text":"Mustafa Kemal, İstanbul’daki 31 Mart Vakası sonrasında Selanik’ten gelen Hareket Ordusunda görev aldı. Olay, ordunun siyasetle ilişkisini tartışmalı biçimde gündeme getirdi.","source":"Atatürk Araştırma Merkezi (ATAM), kaynakçalı Atatürk günlüğü / Atatürk Ansiklopedisi","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Picardie Manevraları","topic":"askerlik, Avrupa","year":"1910","text":"Fransa’da yapılan Picardie askerî manevralarını izledi. Avrupa ordularının tatbikat ve modern savaş yöntemlerini yerinde gözlemledi.","source":"Atatürk Araştırma Merkezi (ATAM), kaynakçalı Atatürk günlüğü / Atatürk Ansiklopedisi","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Trablusgarp’a gidiş","topic":"askerlik, savaş, Libya","year":"1911","text":"İtalyan saldırısı üzerine Trablusgarp’a giden Osmanlı subayları arasında yer aldı. Bölgedeki yerel direnişin örgütlenmesi ve savunma faaliyetlerinde görev yaptı.","source":"Atatürk Araştırma Merkezi (ATAM), kaynakçalı Atatürk günlüğü / Atatürk Ansiklopedisi","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Derne ve Tobruk savunması","topic":"askerlik, savaş","year":"1912","text":"Trablusgarp Savaşı sırasında Derne ve Tobruk çevresindeki savunma faaliyetlerinde bulundu. Bu deneyim, sınırlı imkânlarla yerel güçleri örgütleme pratiği kazandırdı.","source":"Atatürk Araştırma Merkezi (ATAM), kaynakçalı Atatürk günlüğü / Atatürk Ansiklopedisi","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Birinci Dünya Savaşı başlıyor","topic":"savaş, tarih","year":"1914","text":"Birinci Dünya Savaşı’nın başlamasıyla Osmanlı Devleti savaşa katıldı. Mustafa Kemal’in sonraki görevleri cephelerde ve karargâhlarda sürdü.","source":"Atatürk Araştırma Merkezi (ATAM), kaynakçalı Atatürk günlüğü / Atatürk Ansiklopedisi","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Çanakkale Cephesi","topic":"askerlik, savaş, Çanakkale","year":"1915","text":"Çanakkale’de 19. Tümen komutanı olarak görev yaptı; Arıburnu ve Anafartalar çevresindeki muharebelerde öne çıktı. Çanakkale başarısı onu ülke çapında tanınan bir komutan hâline getirdi.","source":"Atatürk Araştırma Merkezi (ATAM), kaynakçalı Atatürk günlüğü / Atatürk Ansiklopedisi","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Doğu Cephesi ve Bitlis","topic":"askerlik, savaş, doğu cephesi","year":"1916","text":"Doğu Cephesi’nde görev yaptı; Muş ve Bitlis’in geri alınması sürecinde komuta sorumluluğu üstlendi. Bu görevler, farklı cephe koşullarında karar verme deneyimini genişletti.","source":"Atatürk Araştırma Merkezi (ATAM), kaynakçalı Atatürk günlüğü / Atatürk Ansiklopedisi","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Yıldırım Orduları ve Suriye","topic":"askerlik, savaş, Suriye","year":"1917","text":"Suriye-Filistin cephesinde görev aldı; savaşın gidişatı ve komuta düzeni üzerine rapor ve değerlendirmeler sundu.","source":"Atatürk Araştırma Merkezi (ATAM), kaynakçalı Atatürk günlüğü / Atatürk Ansiklopedisi","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Mondros sonrasında İstanbul’a dönüş","topic":"Millî Mücadele, siyaset","year":"1918","text":"Mondros Mütarekesi sonrasında İstanbul’a döndü ve ülkenin işgal koşullarını değerlendirdi. Anadolu’da örgütlü bir direniş başlatma fikri bu dönemin siyasi ortamında şekillendi.","source":"Atatürk Araştırma Merkezi (ATAM), kaynakçalı Atatürk günlüğü / Atatürk Ansiklopedisi","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Ankara’ya geliş","topic":"Millî Mücadele, Ankara","year":"27 Aralık 1919","text":"Mustafa Kemal Paşa ve Heyet-i Temsiliye Ankara’ya geldi. Ankara’nın ulaşım ve haberleşme konumu, Millî Mücadele yönetimi için elverişli bir merkez olmasını sağladı.","source":"Atatürk Araştırma Merkezi (ATAM), kaynakçalı Atatürk günlüğü / Atatürk Ansiklopedisi","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Son Osmanlı Mebusan Meclisi","topic":"Millî Mücadele, meclis","year":"12 Ocak 1920","text":"Son Osmanlı Mebusan Meclisi İstanbul’da toplandı. Anadolu’daki seçimlerle belirlenen temsilciler mecliste yer aldı.","source":"Atatürk Araştırma Merkezi (ATAM), kaynakçalı Atatürk günlüğü / Atatürk Ansiklopedisi","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Misak-ı Millî kabulü","topic":"Millî Mücadele, siyaset","year":"28 Ocak 1920","text":"Mebusan Meclisi Misak-ı Millî kararlarını kabul etti. Kararlar, millî sınırlar ve bağımsızlık hedefleri konusunda siyasi çerçeve oluşturdu.","source":"Atatürk Araştırma Merkezi (ATAM), kaynakçalı Atatürk günlüğü / Atatürk Ansiklopedisi","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Hıyanet-i Vataniye Kanunu","topic":"hukuk, TBMM","year":"1920","text":"TBMM, meclisin otoritesine karşı çıkan eylemlerle mücadele için Hıyanet-i Vataniye Kanunu’nu kabul etti. Kanun, savaş dönemindeki olağanüstü siyasal koşullarda çıkarıldı.","source":"Atatürk Araştırma Merkezi (ATAM), kaynakçalı Atatürk günlüğü / Atatürk Ansiklopedisi","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Sevr Antlaşması","topic":"dış politika, savaş","year":"10 Ağustos 1920","text":"Osmanlı Hükûmeti temsilcileri Sevr Antlaşması’nı imzaladı; Ankara’daki TBMM bu anlaşmayı tanımadı. Millî Mücadele, antlaşmanın öngördüğü düzeni kabul etmedi.","source":"Atatürk Araştırma Merkezi (ATAM), kaynakçalı Atatürk günlüğü / Atatürk Ansiklopedisi","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Teşkilât-ı Esasiye Kanunu","topic":"hukuk, siyaset","year":"20 Ocak 1921","text":"TBMM, yeni devletin ilk anayasası olan Teşkilât-ı Esasiye Kanunu’nu kabul etti. Egemenliğin millete ait olduğu ilkesi anayasal düzeyde ifade edildi.","source":"Atatürk Araştırma Merkezi (ATAM), kaynakçalı Atatürk günlüğü / Atatürk Ansiklopedisi","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Moskova Antlaşması","topic":"diplomasi, dış politika","year":"16 Mart 1921","text":"TBMM Hükûmeti ile Sovyet Rusya arasında Moskova Antlaşması imzalandı. İki taraf sınır ve karşılıklı ilişkiler konularını düzenledi.","source":"Atatürk Araştırma Merkezi (ATAM), kaynakçalı Atatürk günlüğü / Atatürk Ansiklopedisi","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Başkomutanlık yetkisi","topic":"askerlik, TBMM","year":"5 Ağustos 1921","text":"TBMM, Mustafa Kemal Paşa’ya üç ay süreyle Başkomutanlık yetkisi verdi. Yetki, ordunun ihtiyaçlarını karşılamak amacıyla Tekâlif-i Milliye emirlerinin çıkarılmasına dayanak oldu.","source":"Atatürk Araştırma Merkezi (ATAM), kaynakçalı Atatürk günlüğü / Atatürk Ansiklopedisi","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Ankara Antlaşması","topic":"diplomasi, dış politika","year":"20 Ekim 1921","text":"TBMM Hükûmeti ile Fransa arasında Ankara Antlaşması imzalandı. Güney cephesindeki çatışmalar sona erdi ve Suriye sınırı düzenlendi.","source":"Atatürk Araştırma Merkezi (ATAM), kaynakçalı Atatürk günlüğü / Atatürk Ansiklopedisi","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Büyük Taarruz’un başlaması","topic":"askerlik, savaş","year":"26 Ağustos 1922","text":"Türk ordusu Büyük Taarruz’u başlattı. Harekâtın hedefi, Yunan ordusunun Anadolu’daki ana kuvvetlerini yenilgiye uğratmaktı.","source":"Atatürk Araştırma Merkezi (ATAM), kaynakçalı Atatürk günlüğü / Atatürk Ansiklopedisi","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Türkiye İktisat Kongresi","topic":"ekonomi, kongre","year":"17 Şubat–4 Mart 1923","text":"İzmir’de toplanan Türkiye İktisat Kongresi, savaş sonrası ekonomik hedefleri tartıştı. Çiftçi, tüccar, sanayici ve işçi temsilcileri kongrede yer aldı.","source":"Atatürk Araştırma Merkezi (ATAM), kaynakçalı Atatürk günlüğü / Atatürk Ansiklopedisi","url":"https://ataturkansiklopedisi.gov.tr/"},{"title":"Lozan Antlaşması","topic":"diplomasi, barış","year":"24 Temmuz 1923","text":"Lozan Barış Antlaşması imzalandı ve yeni Türkiye’nin uluslararası statüsü ile sınırlarına ilişkin düzenlemeler yapıldı. Antlaşma, bağımsızlık mücadelesinin diplomatik sonuçlarından biriydi.","source":"Atatürk Araştırma Merkezi (ATAM), kaynakçalı Atatürk günlüğü / Atatürk Ansiklopedisi","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Ankara’nın başkent oluşu","topic":"siyaset, Ankara","year":"13 Ekim 1923","text":"TBMM, Ankara’yı Türkiye Devleti’nin hükûmet merkezi ilan etti. Ankara, Millî Mücadele yıllarında siyasi merkez ve meclis şehri olmuştu.","source":"Atatürk Araştırma Merkezi (ATAM), kaynakçalı Atatürk günlüğü / Atatürk Ansiklopedisi","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Cumhuriyetin ilanı","topic":"cumhuriyet, siyaset","year":"29 Ekim 1923","text":"TBMM, Cumhuriyet yönetimini ilan etti ve Mustafa Kemal Paşa’yı ilk cumhurbaşkanı seçti. Yeni devletin yönetim biçimi anayasal olarak belirlendi.","source":"Atatürk Araştırma Merkezi (ATAM), kaynakçalı Atatürk günlüğü / Atatürk Ansiklopedisi","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"1924 Anayasası","topic":"hukuk, cumhuriyet","year":"1924","text":"Yeni anayasa cumhuriyet yönetimini, TBMM’nin konumunu ve devlet kurumlarının temel çerçevesini düzenledi. Metin, sonraki yıllarda değişikliklere uğradı.","source":"Atatürk Ansiklopedisi ve ATAM kaynaklı tarih özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Aşar vergisinin kaldırılması","topic":"ekonomi, tarım","year":"17 Şubat 1925","text":"Tarım ürünlerinden alınan aşar vergisi kaldırıldı. Karar, üreticilerin vergi yükünü azaltmaya yönelik erken Cumhuriyet dönemi düzenlemelerindendi.","source":"Atatürk Ansiklopedisi ve ATAM kaynaklı tarih özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Türk Medeni Kanunu","topic":"hukuk, toplum","year":"1926","text":"İsviçre Medeni Kanunu temel alınarak hazırlanan Türk Medeni Kanunu kabul edildi. Aile, miras ve kişiler hukukunda yeni bir yasal çerçeve kuruldu.","source":"Atatürk Ansiklopedisi ve ATAM kaynaklı tarih özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Türk Ceza Kanunu","topic":"hukuk","year":"1926","text":"Yeni Türk Ceza Kanunu kabul edildi. Cumhuriyetin hukuk düzeni, farklı alanlarda yeni kanunlarla yeniden yapılandırıldı.","source":"Atatürk Ansiklopedisi ve ATAM kaynaklı tarih özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Teşvik-i Sanayi Kanunu","topic":"ekonomi, sanayi","year":"1927","text":"Sanayi işletmelerini teşvik etmeyi amaçlayan kanun çıkarıldı. Özel sanayi yatırımlarına destek, dönemin ekonomik kalkınma araçlarından biriydi.","source":"Atatürk Ansiklopedisi ve ATAM kaynaklı tarih özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Yeni Türk harflerinin kabulü","topic":"eğitim, dil","year":"1928","text":"TBMM, Latin temelli yeni Türk alfabesini kabul etti. Ardından yetişkinlere yeni harfleri öğretmek için Millet Mektepleri açıldı.","source":"Atatürk Ansiklopedisi ve ATAM kaynaklı tarih özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Uluslararası rakamların kabulü","topic":"toplum, hukuk","year":"1928","text":"Türkiye’de uluslararası rakamların kullanımı yasayla kabul edildi. Düzenleme, yazı ve hesap işlemlerini uluslararası standartlarla uyumlaştırma adımlarındandı.","source":"Atatürk Ansiklopedisi ve ATAM kaynaklı tarih özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Türk Harfleri Kanunu","topic":"eğitim, hukuk","year":"1 Kasım 1928","text":"Türk harflerinin kullanımını düzenleyen kanun kabul edildi. Yeni yazının öğretilmesi için eğitim seferberliği başlatıldı.","source":"Atatürk Ansiklopedisi ve ATAM kaynaklı tarih özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Kadınlara belediye seçimlerinde seçme ve seçilme hakkı","topic":"kadın hakları, siyaset","year":"1929","text":"Kadınlar belediye seçimlerinde seçme ve seçilme hakkı kazandı. Siyasal hakların genişletilmesi sonraki yıllarda aşamalı olarak devam etti.","source":"Atatürk Ansiklopedisi ve ATAM kaynaklı tarih özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Belediye Kanunu ve kadınların katılımı","topic":"kadın hakları, hukuk","year":"1930","text":"Belediye seçimlerinde kadınların seçme ve seçilme hakkını düzenleyen yasal çerçeve uygulamaya girdi. Kadınlar ilk kez 1930 belediye seçimlerinde oy kullandı.","source":"Atatürk Ansiklopedisi ve ATAM kaynaklı tarih özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Türk kadınlarına belediye seçimlerinde adaylık","topic":"kadın hakları, siyaset","year":"1930","text":"Kadınlar belediye meclislerine seçilebilme hakkını kullandı. Bu gelişme, ulusal düzeydeki siyasal haklardan önce geldi.","source":"Atatürk Ansiklopedisi ve ATAM kaynaklı tarih özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Merkez Bankasının kuruluşu","topic":"ekonomi, kurumlar","year":"1930","text":"Türkiye Cumhuriyet Merkez Bankası kuruldu; banka 1931’de faaliyete geçti. Para politikası ve banknot ihracı için ulusal bir kurum oluşturuldu.","source":"Atatürk Ansiklopedisi ve ATAM kaynaklı tarih özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Türk Tarihi Tetkik Cemiyetinin kuruluşu","topic":"tarih, kurumlar","year":"1931","text":"Türk Tarihi Tetkik Cemiyeti kuruldu; kurum daha sonra Türk Tarih Kurumu adını aldı. Amaçları arasında tarih araştırmalarını kurumsal biçimde yürütmek vardı.","source":"Atatürk Ansiklopedisi ve ATAM kaynaklı tarih özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Türk Dil Kurumunun kuruluşu","topic":"dil, kurumlar","year":"1932","text":"Türk Dili Tetkik Cemiyeti kuruldu ve daha sonra Türk Dil Kurumu adını aldı. Kurum, Türkçenin incelenmesi ve geliştirilmesi için çalışmalar yürüttü.","source":"Atatürk Ansiklopedisi ve ATAM kaynaklı tarih özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Halkevlerinin açılması","topic":"eğitim, kültür","year":"1932","text":"Halkevleri, yetişkin eğitimi ve kültürel etkinlikler için ülke çapında örgütlendi. Şubeleri dil-edebiyat, güzel sanatlar, temsil ve spor gibi alanlarda faaliyet gösterdi.","source":"Atatürk Ansiklopedisi ve ATAM kaynaklı tarih özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Birinci Beş Yıllık Sanayi Planı hazırlıkları","topic":"ekonomi, sanayi","year":"1933","text":"Devlet öncülüğünde sanayi yatırımlarını planlama çalışmaları yürütüldü. Dokuma, kâğıt ve demir-çelik gibi temel sanayi alanları öncelikli sektörler arasındaydı.","source":"Atatürk Ansiklopedisi","url":"https://ataturkansiklopedisi.gov.tr/detay/725/Birinci-Be%C5%9F-Y%C4%B1ll%C4%B1k-Sanayi-Plan%C4%B1"},{"title":"Uluslararası ölçü birimlerine geçiş","topic":"ekonomi, toplum","year":"1935","text":"Metre ve kilogram gibi uluslararası ölçü birimleri kabul edildi. Düzenleme, ölçüm ve ticarette ortak standartların kullanılmasını sağladı.","source":"Atatürk Ansiklopedisi ve ATAM kaynaklı tarih özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Hafta tatilinin pazar gününe alınması","topic":"toplum, hukuk","year":"1935","text":"Hafta tatilini pazar gününe taşıyan düzenleme yürürlüğe girdi. Takvim ve saat düzenlemeleriyle birlikte uluslararası günlük yaşam standartlarına uyum hedeflendi.","source":"Atatürk Ansiklopedisi ve ATAM kaynaklı tarih özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Altı ilkenin anayasaya girmesi","topic":"siyaset, hukuk","year":"1937","text":"Cumhuriyetçilik, milliyetçilik, halkçılık, devletçilik, laiklik ve inkılapçılık ilkeleri 1937’de anayasa metnine eklendi.","source":"Atatürk Ansiklopedisi ve ATAM kaynaklı tarih özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Atatürk’ün vefatı","topic":"yaşam, tarih","year":"1938","text":"Mustafa Kemal Atatürk 10 Kasım 1938’de İstanbul’da Dolmabahçe Sarayı’nda vefat etti. Cenazesi Ankara’ya getirildi ve Etnografya Müzesi’ne geçici olarak konuldu.","source":"Atatürk Ansiklopedisi ve ATAM kaynaklı tarih özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Barışçı dış politika","topic":"dış politika, diplomasi","year":"1923–1938","text":"Cumhuriyet dönemi dış politikası, yeni devletin egemenliğini güvenceye alma ve sorunları diplomasiyle çözme hedefini öne çıkardı. Bölgesel güvenlik anlaşmaları bu yaklaşımın araçlarındandı.","source":"ATAM kaynaklı tarih ve kurum özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Balkan Antantı","topic":"dış politika, diplomasi","year":"1934","text":"Türkiye, Yunanistan, Yugoslavya ve Romanya 1934’te Balkan Antantı’nı imzaladı. Antant, Balkan sınırlarının korunması ve bölgesel güvenlik iş birliğini hedefledi.","source":"Atatürk Ansiklopedisi","url":"https://ataturkansiklopedisi.gov.tr/detay/682/Balkan-Antant%C4%B1"},{"title":"Sadabat Paktı","topic":"dış politika, diplomasi","year":"1937","text":"Türkiye, İran, Irak ve Afganistan 1937’de Sadabat Paktı’nı imzaladı. Anlaşma, bölgesel saldırmazlık ve iyi komşuluk ilişkilerine yönelikti.","source":"ATAM kaynaklı tarih ve kurum özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Musul sorununun çözümü","topic":"dış politika, diplomasi","year":"1926","text":"Türkiye ile İngiltere arasında yapılan anlaşmayla Musul’un Irak’a bırakılması kabul edildi. Lozan’da çözülemeyen konu diplomatik müzakerelerle karara bağlandı.","source":"Atatürk Ansiklopedisi","url":"https://ataturkansiklopedisi.gov.tr/detay/907/Atat%C3%BCrk-D%C3%B6nemi-T%C3%BCrkiye-Orta-Do%C4%9Fu-%C4%B0li%C5%9Fkileri"},{"title":"Hatay’ın Türkiye’ye katılması süreci","topic":"dış politika, Hatay","year":"1936–1939","text":"Hatay meselesi uluslararası görüşmeler ve yerel siyasi gelişmelerle ilerledi. Hatay Devleti 1938’de kuruldu; Türkiye’ye katılma 1939’da, Atatürk’ün ölümünden sonra gerçekleşti.","source":"Atatürk Ansiklopedisi","url":"https://ataturkansiklopedisi.gov.tr/detay/907/Atat%C3%BCrk-D%C3%B6nemi-T%C3%BCrkiye-Orta-Do%C4%9Fu-%C4%B0li%C5%9Fkileri"},{"title":"Yunanistan ile yakınlaşma","topic":"dış politika, diplomasi","year":"1930","text":"Türkiye ile Yunanistan arasındaki ilişkiler 1930’larda normalleşme yönünde ilerledi. Balkan iş birliği girişimleri bu yakınlaşmanın bölgesel boyutunu oluşturdu.","source":"ATAM kaynaklı tarih ve kurum özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"İzmir İktisat Kongresi’nin bileşimi","topic":"ekonomi, temsil","year":"1923","text":"Kongrede çiftçi, tüccar, sanayici ve işçi gruplarının temsilcileri yer aldı. Toplantı, savaş sonrasında ekonomik öncelikleri ortaklaşa tartışma girişimiydi.","source":"Atatürk Ansiklopedisi","url":"https://ataturkansiklopedisi.gov.tr/detay/438/T%C3%BCrkiye-%C4%B0ktisat-Kongresi"},{"title":"Misak-ı İktisadi","topic":"ekonomi, kongre","year":"1923","text":"İzmir İktisat Kongresi’nde kabul edilen Misak-ı İktisadi, ekonomik yaşama ilişkin ortak hedef ve ilkeleri duyurdu. Kongre, üretim ve ulusal ekonomik bağımsızlık tartışmalarına alan açtı.","source":"ATAM kaynaklı tarih ve kurum özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Dünya ekonomik bunalımının etkisi","topic":"ekonomi, tarih","year":"1929–1930","text":"Dünya ekonomik bunalımı Türkiye’nin dış ticaretini ve ekonomik tercihlerini etkiledi. Devletin sanayi yatırımlarındaki rolü 1930’larda arttı.","source":"Atatürk Ansiklopedisi","url":"https://ataturkansiklopedisi.gov.tr/detay/174/1929-Ekonomik-Buhran%C4%B1"},{"title":"Devletçilik ve karma ekonomi","topic":"ekonomi, devletçilik","year":"1930’lar","text":"Atatürk dönemi devletçiliği, özel girişimin yetersiz kaldığı alanlarda devlet yatırımlarını artırdı. Uygulama, devlet ve özel sektörün birlikte bulunduğu karma ekonomik yapı içinde gelişti.","source":"Atatürk Ansiklopedisi","url":"https://ataturkansiklopedisi.gov.tr/bilgi/ataturk-ilkeleri/?pdf=3798"},{"title":"Demiryolu yatırımları","topic":"ekonomi, ulaşım","year":"1930’lar","text":"Demiryolu ağının genişletilmesi, iç bölgeleri limanlara ve pazarlara bağlama hedefi taşıdı. Ulaşım yatırımları ekonomik bütünleşme ve güvenlik açısından önemsendi.","source":"ATAM kaynaklı tarih ve kurum özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Tarımın geliştirilmesi","topic":"ekonomi, tarım","year":"1930’lar","text":"Cumhuriyet yönetimi tarımsal üretimi artırmak için tohum, fidan, hayvancılık ve tarımsal eğitim konularında kurumlar ve uygulamalar geliştirdi.","source":"ATAM kaynaklı tarih ve kurum özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Sümerbank ve sanayileşme","topic":"ekonomi, kurumlar","year":"1930’lar","text":"Sümerbank, devlet sanayi kuruluşlarının işletilmesi ve yeni fabrika yatırımlarının düzenlenmesinde rol aldı. Tekstil başta olmak üzere sanayi alanlarına finansman ve teknik destek sağladı.","source":"ATAM kaynaklı tarih ve kurum özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Etibank’ın kurulması","topic":"ekonomi, kurumlar","year":"1930’lar","text":"Etibank, maden kaynaklarının değerlendirilmesi ve enerji yatırımlarının geliştirilmesi için kuruldu. Madencilik, sanayi politikasıyla bağlantılı bir kalkınma alanıydı.","source":"ATAM kaynaklı tarih ve kurum özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Fabrikalar ve yerli üretim","topic":"ekonomi, sanayi","year":"1930’lar","text":"Devlet yatırımları dokuma, şeker, kâğıt ve temel sanayi gibi alanlarda üretim kapasitesi oluşturmayı hedefledi. Bu tesisler ithalat bağımlılığını azaltma amacıyla ilişkilendirildi.","source":"ATAM kaynaklı tarih ve kurum özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Bilimsel kurumların rolü","topic":"bilim, kurumlar","year":"1930’lar","text":"Türk Tarih Kurumu ve Türk Dil Kurumu gibi kurumlar, tarih ve dil araştırmalarını düzenli ve örgütlü biçimde yürütmek üzere çalıştı.","source":"ATAM kaynaklı tarih ve kurum özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Maarif Kongresi","topic":"eğitim, kongre","year":"1921","text":"Ankara’da toplanan Maarif Kongresi, savaş sürerken eğitim sorunlarını ve eğitim politikasının yönünü ele aldı. Öğretmenler ve eğitimciler toplantıya katıldı.","source":"ATAM kaynaklı tarih ve kurum özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Üniversite reformunda yabancı akademisyenler","topic":"eğitim, bilim","year":"1933","text":"İstanbul Üniversitesi reformu sırasında Almanya’dan ayrılmak zorunda kalan bazı akademisyenler Türkiye’de görev aldı. Bu gelişme, yükseköğretim kadrolarını ve bilimsel çalışmaları etkiledi.","source":"ATAM kaynaklı tarih ve kurum özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Dil ve tarih kurultayları","topic":"bilim, tarih, dil","year":"1936","text":"Türk dili ve tarihi üzerine kurumsal araştırmalar, kurultaylar ve yayınlarla desteklendi. Bu tartışmaların dönemin bilimsel standartlarıyla ilişkisi ayrıca tarihsel bağlam içinde değerlendirilmelidir.","source":"ATAM kaynaklı tarih ve kurum özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Kadınların kamusal yaşama katılımı","topic":"kadın hakları, toplum","year":"1930’lar","text":"Eğitim ve siyasal haklardaki değişiklikler kadınların kamusal yaşama katılımını genişletti. Uygulama, dönemin toplumsal koşulları ve sınırları içinde değerlendirilmelidir.","source":"Atatürk Ansiklopedisi","url":"https://ataturkansiklopedisi.gov.tr/detay/919/Atat%C3%BCrk-D%C3%B6neminde-Kad%C4%B1n-Haklar%C4%B1"},{"title":"Hukuk devriminin kapsamı","topic":"hukuk, toplum","year":"1930’lar","text":"Cumhuriyet dönemindeki hukuk düzenlemeleri medeni hukuk, ceza hukuku ve ticaret gibi alanları yeniden düzenledi. Hukuk değişiklikleri, devlet ve toplum yapısını etkileyen geniş bir dönüşümün parçasıydı.","source":"Atatürk Ansiklopedisi","url":"https://ataturkansiklopedisi.gov.tr/detay/848/Atat%C3%BCrk-ve-Hukuk-Devrimi"},{"title":"Laiklik ve kamu yönetimi","topic":"hukuk, siyaset","year":"1930’lar","text":"Laiklik ilkesi, devlet işlerinin ve kamu hizmetlerinin dinî otoriteden bağımsız bir hukuk çerçevesinde yürütülmesi anlayışıyla ilişkilendirildi. Tarihsel uygulama kendi dönemi ve kanunları içinde incelenmelidir.","source":"Atatürk Ansiklopedisi","url":"https://ataturkansiklopedisi.gov.tr/detay/851/Atat%C3%BCrk-ve-Laiklik"},{"title":"Nutuk’un okunması","topic":"eserler, tarih","year":"1927","text":"Atatürk, Nutuk’u 15–20 Ekim 1927’de Cumhuriyet Halk Partisi İkinci Kurultayı’nda okudu. Eser, 1919’dan 1927’ye uzanan Millî Mücadele ve kuruluş dönemini kendi anlatımıyla ele alır.","source":"ATAM kaynaklı tarih ve kurum özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Söylev ve demeçlerin derlenmesi","topic":"eserler, kaynak","year":"1906–1938","text":"ATAM’ın üç ciltlik derlemesi, 1906–1938 döneminden Atatürk’e ait söylev, demeç ve yazıları bir araya getirir. Alıntılar tarih, yer ve bağlamıyla birlikte incelenmelidir.","source":"ATAM kaynaklı tarih ve kurum özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Türk Tarih Tezi tartışmaları","topic":"tarih, bilim","year":"1931","text":"Türk tarihine ilişkin yeni yorumlar 1930’larda ders kitapları, kurultaylar ve kurum çalışmaları içinde geliştirildi. Bu tezler günümüz tarihçiliğinde kaynak ve yöntem açısından eleştirel olarak incelenir.","source":"ATAM kaynaklı tarih ve kurum özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Birinci Türk Dil Kurultayı","topic":"dil, bilim","year":"1932","text":"Türk Dili Tetkik Cemiyetinin ilk kurultayı 1932’de toplandı. Kurultayda Türkçenin incelenmesi, söz varlığı ve dil çalışmaları ele alındı.","source":"ATAM kaynaklı tarih ve kurum özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Dil reformu ve terim üretimi","topic":"dil, bilim","year":"1930’lar","text":"Dil çalışmaları, Türkçe terimlerin geliştirilmesini ve yazı dilinin düzenlenmesini amaçladı. Bu süreçte önerilen bazı dil açıklamaları daha sonra bilimsel inceleme ve düzeltmelere konu oldu.","source":"ATAM kaynaklı tarih ve kurum özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Ankara’nın yeni başkent olarak gelişmesi","topic":"şehir, siyaset","year":"1920’ler","text":"Ankara, başkent olduktan sonra yeni kamu binaları, ulaşım ve planlama yatırımlarıyla büyüdü. Cumhuriyetin idari merkezinin İstanbul dışında kurulması devlet yapısının yeniden örgütlenmesini simgeledi.","source":"ATAM kaynaklı tarih ve kurum özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Cumhuriyetin kurumsallaşması","topic":"siyaset, kurumlar","year":"1920’ler","text":"TBMM, bakanlıklar ve yeni anayasal düzen, savaş zamanı yönetiminden kalıcı devlet kurumlarına geçiş sürecini oluşturdu. Kurumsal değişim birkaç yıla yayıldı.","source":"ATAM kaynaklı tarih ve kurum özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Devlet-halk ilişkisi","topic":"siyaset, toplum","year":"1930’lar","text":"Halkçılık ilkesi, siyasal ayrıcalıkların reddi ve yurttaşlık temelinde birlik söylemiyle açıklandı. Dönemin siyasal sistemi ve uygulamaları bu resmî ilkeyle birlikte ele alınmalıdır.","source":"ATAM kaynaklı tarih ve kurum özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Akıl ve bilim vurgusu","topic":"bilim, düşünce","year":"1930’lar","text":"ATAM’ın düşünce derlemelerinde akıl, bilim ve gerçekçilik karar alma ilkeleri olarak öne çıkar. Bu ifadeler kaynak ve bağlam denetlenerek kullanılmalıdır.","source":"ATAM kaynaklı tarih ve kurum özeti","url":"https://atam.gov.tr/akilcilik-bilimcilik-gerceklik/"},{"title":"Eğitimin toplumsal rolü","topic":"eğitim, toplum","year":"1930’lar","text":"Cumhuriyet döneminde eğitim, okuryazarlık ve meslekî yeterlilikleri artırmanın yanı sıra ortak bir kamusal kültür oluşturma aracı olarak görüldü.","source":"ATAM kaynaklı tarih ve kurum özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Köy eğitimi ve öğretmenlik","topic":"eğitim, tarih","year":"1930’lar","text":"Öğretmen yetiştirme ve kırsal bölgelerde okul hizmetini yaygınlaştırma, Cumhuriyetin eğitim gündemindeki temel meseleler arasındaydı. Köy Enstitüleri 1940’ta, Atatürk’ün ölümünden sonra kuruldu.","source":"ATAM kaynaklı tarih ve kurum özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Sağlık kurumlarının gelişimi","topic":"sağlık, kurumlar","year":"1920’ler","text":"Savaş sonrasında sağlık hizmetlerini örgütleme, salgınlarla mücadele ve sağlık personeli yetiştirme yeni devletin temel kamu hizmetleri arasına girdi.","source":"ATAM kaynaklı tarih ve kurum özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Sanayi planlamasının amaçları","topic":"ekonomi, sanayi","year":"1930’lar","text":"Sanayi planlaması, ülke içinde temel malların üretimini artırma ve yatırımları öncelikli sektörlere yöneltme hedefi taşıdı. Planların uygulanması finansman ve uzmanlık kapasitesiyle sınırlıydı.","source":"ATAM kaynaklı tarih ve kurum özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"İktisadi bağımsızlık düşüncesi","topic":"ekonomi, siyaset","year":"1930’lar","text":"Dönem kaynakları siyasal bağımsızlığın kalıcılığını ekonomik kapasiteyle ilişkilendirir. İzmir İktisat Kongresi ve sanayi politikaları bu hedef doğrultusunda değerlendirilebilir.","source":"ATAM kaynaklı tarih ve kurum özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Montrö’nün güvenlik boyutu","topic":"dış politika, savunma","year":"1936","text":"Montrö rejimi ticaret gemilerinin geçişini düzenlerken savaş gemileri için farklı kurallar belirledi. Sözleşme, Karadeniz ve Boğazların güvenliğini uluslararası bir çerçeveye bağladı.","source":"Atatürk Ansiklopedisi","url":"https://ataturkansiklopedisi.gov.tr/detay/355/Montreux_%28Montr%C3%B6%29_Bo%C4%9Fazlar_S%C3%B6zle%C5%9Fmesi_%2822_Haziran-20_Temmuz_1936%29"},{"title":"Balkan iş birliği ve sınır güvenliği","topic":"dış politika, güvenlik","year":"1934","text":"Balkan Antantı, üye ülkelerin mevcut sınırları korumaya dönük ortak iradesini gösterdi. Antantın bağlayıcı bir ortak savunma mekanizması sınırlıydı.","source":"Atatürk Ansiklopedisi","url":"https://ataturkansiklopedisi.gov.tr/detay/682/Balkan-Antant%C4%B1"},{"title":"Komşularla ilişkilerde gerçekçilik","topic":"dış politika, diplomasi","year":"1923–1938","text":"Türkiye, sorunlarını çözmeye çalışırken güç dengelerini ve dönemin uluslararası şartlarını hesaba kattı. Bu yaklaşımın örnekleri Lozan, Musul ve Boğazlar dosyalarında görülebilir.","source":"ATAM kaynaklı tarih ve kurum özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Vasiyet ve mal varlığı","topic":"yaşam, hukuk","year":"1938","text":"Atatürk, mal varlığının önemli bölümünü Cumhuriyet Halk Partisine bıraktı; vasiyetinde yakınlarına ve bazı kurumlara yönelik düzenlemeler de yer aldı. Ayrıntılar vasiyetname metninden doğrulanmalıdır.","source":"ATAM kaynaklı tarih ve kurum özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Defin yeri ve Anıtkabir","topic":"yaşam, anma","year":"1938","text":"Atatürk’ün naaşı 1953’e kadar Ankara Etnografya Müzesi’nde kaldı; Anıtkabir’e nakil Atatürk’ün ölümünden yıllar sonra gerçekleştirildi.","source":"ATAM kaynaklı tarih ve kurum özeti","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Mustafa Kemal’in ailesi","topic":"yaşam, aile","year":"1881–1890’lar","text":"Mustafa Kemal’in annesi Zübeyde Hanım, babası Ali Rıza Efendi’dir. Kardeşleri arasında Makbule Hanım da bulunur.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Mahalle mektebi ve Şemsi Efendi Okulu","topic":"eğitim, çocukluk","year":"1880’ler","text":"Mustafa Kemal’in ilk öğreniminde mahalle mektebi ve Şemsi Efendi Mektebi yer aldı. Eğitim tercihi ailesinin beklentileriyle şekillendi.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://ataturkansiklopedisi.gov.tr/"},{"title":"Selanik’in çok kültürlü ortamı","topic":"şehir, yaşam","year":"1881–1912","text":"Selanik, Osmanlı döneminde farklı dinî ve etnik toplulukların yaşadığı hareketli bir liman kentiydi. Bu çevre Mustafa Kemal’in yetiştiği toplumsal ortamın parçasıydı.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://ataturkansiklopedisi.gov.tr/"},{"title":"Manastır’da tarih ve edebiyat","topic":"eğitim, kültür","year":"1896–1899","text":"Manastır Askerî İdadisinde okuduğu yıllar, Mustafa Kemal’in tarih, şiir ve hitabetle ilgilendiği gençlik dönemine rastlar.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://ataturkansiklopedisi.gov.tr/"},{"title":"Namık Kemal’in etkisi","topic":"kültür, düşünce","year":"gençlik dönemi","text":"Gençlik yıllarında Namık Kemal’in eserleriyle tanışması, vatan ve özgürlük konularına ilgisini besleyen kültürel etkenlerden biri olarak anlatılır.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://ataturkansiklopedisi.gov.tr/"},{"title":"Kurmay subaylık eğitimi","topic":"askerlik, eğitim","year":"1902–1905","text":"Harp Akademisindeki eğitim; askerî tarih, strateji ve kurmaylık derslerini kapsıyordu. Mustafa Kemal akademiyi kurmay yüzbaşı rütbesiyle tamamladı.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Vatan ve Hürriyet oluşumu","topic":"siyaset, askerlik","year":"1906","text":"Şam’da görevliyken Mustafa Kemal ve bazı arkadaşları Vatan ve Hürriyet adlı gizli örgütlenmeyi kurdu. Dönemin istibdat yönetimine karşı siyasal muhalefet ortamında faaliyet gösterdi.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"İkinci Meşrutiyet dönemi","topic":"siyaset, tarih","year":"1908","text":"II. Meşrutiyet’in ilanı Osmanlı yönetiminde anayasal ve parlamenter siyasetin yeniden başlamasını sağladı. Mustafa Kemal bu dönemde ordudaki görevini sürdürdü.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Trablusgarp’ta yerel savunma","topic":"askerlik, savaş","year":"1911–1912","text":"Osmanlı subayları Trablusgarp’ta yerel halktan birlikler oluşturarak İtalyan kuvvetlerine karşı mücadele etti. Mustafa Kemal Tobruk ve Derne çevresinde görev yaptı.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://ataturkansiklopedisi.gov.tr/"},{"title":"Balkan Savaşlarının sonucu","topic":"savaş, tarih","year":"1912–1913","text":"Balkan Savaşları Osmanlı Devleti’nin Avrupa’daki topraklarının büyük bölümünü kaybetmesine yol açtı. Mustafa Kemal, savaş yıllarında Gelibolu ve Bolayır çevresindeki görevlerde bulundu.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Sofya’da diplomatik gözlem","topic":"diplomasi, askerlik","year":"1913–1914","text":"Sofya askerî ataşeliği, Mustafa Kemal’in yabancı başkentte diplomatik temsilcilik görevini yürüttüğü dönemdir. Bulgaristan’ın askerî ve siyasi durumunu raporladı.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Çanakkale’de 19. Tümen","topic":"askerlik, savaş","year":"1915","text":"Mustafa Kemal, 19. Tümen komutanı olarak Çanakkale savunmasında görev aldı. Tümen, Arıburnu bölgesindeki muharebelerde önemli rol üstlendi.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://ataturkansiklopedisi.gov.tr/"},{"title":"Anafartalar Grubu komutanlığı","topic":"askerlik, savaş","year":"1915","text":"Anafartalar muharebeleri sırasında Mustafa Kemal, Anafartalar Grubu komutanlığını yürüttü. Ağustos 1915’teki çatışmalar Çanakkale kara savaşlarının önemli safhalarındandı.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://ataturkansiklopedisi.gov.tr/"},{"title":"Çanakkale’nin stratejik sonucu","topic":"askerlik, tarih","year":"1915","text":"İtilaf kuvvetleri Çanakkale Boğazı’nı geçerek İstanbul’a ulaşamadı ve Gelibolu Yarımadası’ndan çekildi. Cephedeki savunma, savaşın genel seyrini etkiledi.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Doğu cephesinde kolordu komutanlığı","topic":"askerlik, savaş","year":"1916","text":"Mustafa Kemal, Doğu Cephesi’nde 16. Kolordu komutanlığı yaptı. Bölgedeki Rus ilerleyişine karşı yürütülen askerî harekâtlarda sorumluluk üstlendi.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Muş ve Bitlis’in geri alınması","topic":"askerlik, savaş","year":"1916","text":"Rus işgali altındaki Muş ve Bitlis’in geri alınması, 1916 Doğu Cephesi harekâtlarının önemli sonuçları arasındaydı. Mustafa Kemal bu cephede komuta görevindeydi.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Veliaht Vahdettin’in Almanya gezisi","topic":"diplomasi, askerlik","year":"1917","text":"Mustafa Kemal, Veliaht Vahdettin’in Almanya gezisine eşlik etti. Avrupa’daki askerî durumu ve Alman komuta çevrelerini gözlemledi.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Suriye cephesinde 7. Ordu","topic":"askerlik, savaş","year":"1917–1918","text":"Mustafa Kemal, Suriye-Filistin cephesinde 7. Ordu komutanı olarak görev yaptı. Geri çekilme döneminde ordunun korunmasına ve yeniden düzenlenmesine çalıştı.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Yıldırım Orduları Grubu","topic":"askerlik, tarih","year":"1918","text":"Mustafa Kemal, Mondros öncesinde Yıldırım Orduları Grubu komutanlığı görevini üstlendi. Mütareke sonrasında bu komutanlık dağıtıldı ve İstanbul’a döndü.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Samsun’dan Havza’ya geçiş","topic":"Millî Mücadele, örgütlenme","year":"Mayıs 1919","text":"Samsun’a çıktıktan sonra Havza’ya geçen Mustafa Kemal Paşa, işgallere karşı protesto ve örgütlenme çağrılarının yayılmasına katkı sağladı.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Mustafa Kemal’in askerlikten ayrılması","topic":"Millî Mücadele, yaşam","year":"Temmuz 1919","text":"İstanbul Hükûmeti’nin geri çağırma baskısı sırasında Mustafa Kemal askerlik görevinden ayrıldı. Mücadeleyi sivil ve siyasi bir lider olarak sürdürdü.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Erzurum Kongresi’nin kapsamı","topic":"Millî Mücadele, kongre","year":"1919","text":"Erzurum Kongresi başlangıçta doğu illerinin savunmasına yönelik planlanmıştı. Mustafa Kemal’in başkanlığı ve alınan kararlar kongrenin ulusal etkisini genişletti.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://ataturkansiklopedisi.gov.tr/detay/673/Erzurum-Kongresi"},{"title":"Sivas Kongresi’nde cemiyetlerin birleşmesi","topic":"Millî Mücadele, örgütlenme","year":"1919","text":"Sivas Kongresi, Anadolu ve Rumeli’deki Müdafaa-i Hukuk cemiyetlerini tek örgüt çatısı altında toplama kararı aldı. Bu birleşme mücadele koordinasyonunu güçlendirdi.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://ataturkansiklopedisi.gov.tr/detay/294/Sivas-Kongresi"},{"title":"Temsil Heyeti’nin görev alanı","topic":"Millî Mücadele, siyaset","year":"1919","text":"Sivas Kongresi sonrasında Heyet-i Temsiliye ülke çapındaki direniş örgütlerini temsil ve yönetme sorumluluğunu üstlendi. Ankara’ya gelişe kadar çalışmalarını Anadolu’da sürdürdü.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Misak-ı Millî’nin ilanı","topic":"Millî Mücadele, siyaset","year":"17 Şubat 1920","text":"Son Osmanlı Mebusan Meclisi, Misak-ı Millî kararlarını 17 Şubat 1920’de kamuoyuna duyurdu. Kararlar, bağımsızlık ve millî sınırlar taleplerini özetledi.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"TBMM’nin ilk başkanı","topic":"TBMM, siyaset","year":"1920","text":"Mustafa Kemal, TBMM açıldığında Meclis Başkanlığına seçildi. Meclis başkanlığı, Millî Mücadele’nin siyasi liderliğiyle birlikte yürüttüğü temel görevlerden biri oldu.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Kars Antlaşması","topic":"diplomasi, dış politika","year":"13 Ekim 1921","text":"TBMM Hükûmeti ile Sovyet Ermenistanı, Azerbaycan ve Gürcistan arasında Kars Antlaşması imzalandı. Doğu sınırının belirlenmesine ilişkin düzenlemeler yapıldı.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Sakarya zaferinin diplomatik etkisi","topic":"diplomasi, savaş","year":"1921","text":"Sakarya zaferinden sonra Fransa ile Ankara Antlaşması imzalandı; İtilaf devletlerinin TBMM Hükûmetiyle ilişkileri değişmeye başladı. Askerî sonuç diplomatik alanı etkiledi.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Mudanya görüşmelerindeki taraflar","topic":"diplomasi, barış","year":"1922","text":"Mudanya görüşmelerine TBMM Hükûmeti ile İngiltere, Fransa ve İtalya temsilcileri katıldı. Yunanistan görüşmelere doğrudan değil, temsilcileri aracılığıyla dahil oldu.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Lozan Konferansı’nın kesintisi","topic":"diplomasi, tarih","year":"1923","text":"Lozan görüşmeleri Şubat 1923’te kesildi ve Türk heyeti Ankara’ya döndü; görüşmeler Nisan ayında yeniden başladı. Süreçte kapitülasyonlar, sınırlar ve borçlar tartışıldı.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Lozan’da çözülemeyen Musul","topic":"dış politika, diplomasi","year":"1923–1926","text":"Musul konusu Lozan’da çözüme bağlanamadı ve Türkiye ile İngiltere arasında sonraki müzakerelere bırakıldı. Sorun 1926 Ankara Antlaşması ile sonuçlandırıldı.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://ataturkansiklopedisi.gov.tr/detay/907/Atat%C3%BCrk-D%C3%B6nemi-T%C3%BCrkiye-Orta-Do%C4%9Fu-%C4%B0li%C5%9Fkileri"},{"title":"Cumhuriyet döneminin ilk kabinesi","topic":"siyaset, kurumlar","year":"1923","text":"Cumhuriyet ilanından sonra İsmet Paşa başkanlığında yeni hükûmet kuruldu. Cumhurbaşkanlığı ve başbakanlık makamları yeni anayasal yönetim içinde tanımlandı.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Cumhurbaşkanlığı dönemi","topic":"siyaset, yaşam","year":"1923–1938","text":"Atatürk, 1923’ten 1938’deki vefatına kadar Türkiye Cumhuriyeti’nin cumhurbaşkanlığını yaptı. Bu dönemde anayasal kurumlar ve yönetim biçimi değişti.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"1924 Anayasası’nın kabulü","topic":"hukuk, anayasa","year":"20 Nisan 1924","text":"TBMM, 1924 Teşkilât-ı Esasiye Kanunu’nu kabul etti. Anayasa, devlet organlarının görev ve ilişkilerini düzenledi.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"İzmir Suikastı davası","topic":"siyaset, tarih","year":"1926","text":"Mustafa Kemal’e yönelik İzmir’de planlanan suikast girişimi ortaya çıkarıldı. Dava sonrasında çok sayıda kişi yargılandı; olayın siyasal bağlamı tarihçilerce incelenir.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Medeni Kanun ve kadınların hukuki statüsü","topic":"kadın hakları, hukuk","year":"1926","text":"Türk Medeni Kanunu medeni nikâh, boşanma, miras ve aile hukukunu yeniden düzenledi. Kanun, kadınların medeni hukuk alanındaki statüsünü dönüştüren hükümler içerdi.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://ataturkansiklopedisi.gov.tr/"},{"title":"Millet Mektepleri Başöğretmenliği","topic":"eğitim, yaşam","year":"24 Kasım 1928","text":"Yeni alfabe öğretimi sırasında Atatürk’e Millet Mektepleri Başöğretmenliği unvanı verildi. 24 Kasım daha sonra Öğretmenler Günü olarak kutlanmaya başladı.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"1930 belediye seçimlerinde kadınlar","topic":"kadın hakları, seçim","year":"1930","text":"Kadınlar 1930 belediye seçimlerinde oy kullandı ve belediye meclislerine seçilebilme hakkını uygulamaya başladı. Ulusal seçimlerdeki haklar 1934’te tanındı.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"İlk kadın muhtar","topic":"kadın hakları, yerel yönetim","year":"1933","text":"Aydın’ın Çine ilçesine bağlı Demircidere köyünde Gül Esin, Türkiye’nin ilk kadın muhtarı seçildi. Bu gelişme, kadınların yerel yönetime katılımının örneğidir.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"1935 seçimleri ve kadın milletvekilleri","topic":"kadın hakları, siyaset","year":"1935","text":"1934’te tanınan hakların ardından 1935 genel seçimlerinde kadınlar milletvekili seçildi. İlk kadın milletvekilleri TBMM’de görev almaya başladı.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Soyadı Kanunu’nun toplumsal amacı","topic":"hukuk, toplum","year":"1934","text":"Soyadı Kanunu, resmî işlemlerde kişilerin aile adlarıyla tanımlanmasını ve adlandırma düzeninin standartlaşmasını sağladı. Atatürk soyadını Meclis kararıyla aldı.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Türk Tarih Kurumunun adı","topic":"tarih, kurumlar","year":"1931–1935","text":"Türk Tarihi Tetkik Cemiyeti 1935’te Türk Tarih Kurumu adını aldı. Kurum, tarih araştırmaları ve yayınları için sürekli bir yapı oluşturdu.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Türk Dil Kurumunun adı","topic":"dil, kurumlar","year":"1932–1936","text":"Türk Dili Tetkik Cemiyeti 1936’da Türk Dil Kurumu adını aldı. Kurum, dil araştırmaları, sözlük çalışmaları ve terim üretimi yürüttü.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Türk Tarih Kongreleri","topic":"tarih, bilim","year":"1932 ve sonrası","text":"Türk Tarih Kurumu, tarih araştırmalarını tartışmak ve yayımlamak için kongreler düzenledi. Kongrelerde sunulan görüşler kendi dönemlerinin bilimsel bağlamı içinde değerlendirilmelidir.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Dil kurultayları","topic":"dil, bilim","year":"1932 ve sonrası","text":"Türk Dil Kurumu kurultayları dil çalışmaları ve yazı dili üzerine görüş alışverişi sağladı. Kurultaylar, dil reformunun kurumlaşmış tartışma alanları oldu.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Ankara Hukuk Mektebi","topic":"eğitim, hukuk","year":"1925","text":"Ankara Hukuk Mektebi, yeni hukuk düzenine uygun hukukçu yetiştirmek üzere açıldı. Kurum daha sonra Ankara Üniversitesi Hukuk Fakültesine dönüştü.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://ataturkansiklopedisi.gov.tr/"},{"title":"Mektep ve medrese ayrımının sona erdirilmesi","topic":"eğitim, hukuk","year":"1924","text":"Tevhid-i Tedrisat Kanunu ile farklı idarelere bağlı eğitim kurumları Eğitim Bakanlığına bağlandı. Kanun, eğitimde merkezi idareyi güçlendirdi.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://ataturkansiklopedisi.gov.tr/bilgi/tevhid-i-tedrisat-kanunu/?pdf=3327"},{"title":"Dinî yükseköğretim düzenlemesi","topic":"eğitim, din","year":"1924","text":"Tevhid-i Tedrisat Kanunu, üniversite bünyesinde İlahiyat Fakültesi kurulmasını ve din hizmetleri için eğitim kurumları açılmasını öngördü.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://ataturkansiklopedisi.gov.tr/bilgi/tevhid-i-tedrisat-kanunu/?pdf=3327"},{"title":"Yabancı okulların denetlenmesi","topic":"eğitim, hukuk","year":"1920’ler","text":"Cumhuriyet döneminde yabancı ve azınlık okullarının eğitim mevzuatına uyması ve devlet denetimine alınması için düzenlemeler yapıldı.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://ataturkansiklopedisi.gov.tr/bilgi/tevhid-i-tedrisat-kanunu/?pdf=3327"},{"title":"Köy Enstitülerinin kuruluş tarihi","topic":"eğitim, kronoloji","year":"1940","text":"Köy Enstitüleri 1940’ta, Atatürk’ün ölümünden sonra kuruldu. Köy öğretmeni yetiştirme projesini Atatürk döneminde tamamlanmış bir reform gibi göstermemek gerekir.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://ataturkansiklopedisi.gov.tr/"},{"title":"İstanbul Üniversitesi reformu ve Darülfünun","topic":"eğitim, bilim","year":"1933","text":"Üniversite reformuyla Darülfünun kapatıldı ve yerine İstanbul Üniversitesi kuruldu. Reform, yükseköğretimin yapısını ve öğretim kadrosunu yeniledi.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Türk Hava Kurumunun kuruluşu","topic":"havacılık, kurumlar","year":"1925","text":"Türk Tayyare Cemiyeti 1925’te kuruldu; kurum daha sonra Türk Hava Kurumu adını aldı. Havacılığın geliştirilmesi sivil toplum ve bağış kampanyalarıyla desteklendi.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Türkkuşu’nun açılışı","topic":"bilim, havacılık","year":"1935","text":"Türkkuşu, havacılık eğitimi ve paraşütçülük faaliyetleri yürütmek üzere 1935’te açıldı. Kurumun çalışmaları gençlerin havacılığa yönelmesini amaçladı.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"İlk kadın pilot Sabiha Gökçen","topic":"havacılık, kadınlar","year":"1930’lar","text":"Sabiha Gökçen, Türkiye’nin ilk kadın pilotu ve dünyanın ilk kadın savaş pilotlarından biri olarak anılır. 1930’larda Türkkuşu ve askerî havacılık eğitimlerinde yetişti.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://ataturkansiklopedisi.gov.tr/"},{"title":"Demiryollarında devletleştirme","topic":"ekonomi, ulaşım","year":"1920–1930’lar","text":"Yeni devlet, yabancı şirketlerin işlettiği bazı demiryolu hatlarını satın alarak ulusal demiryolu ağını genişletti. Demiryolları savunma ve ekonomik bütünleşme için önemliydi.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"İzmir-Aydın demiryolu","topic":"ekonomi, ulaşım","year":"1920’ler","text":"İzmir-Aydın hattı, Osmanlı döneminde yabancı sermayeyle işletilen demiryolu örneklerindendi. Cumhuriyet döneminde demiryolu ağının yerli denetime geçmesi ve genişlemesi hedeflendi.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://ataturkansiklopedisi.gov.tr/"},{"title":"Şeker fabrikaları","topic":"ekonomi, sanayi","year":"1920–1930’lar","text":"Alpullu ve Uşak şeker fabrikaları 1926’da üretime başladı. Şeker sanayisinin kurulması, tarım ile sanayiyi buluşturan erken Cumhuriyet yatırımlarındandı.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Kayseri Uçak Fabrikası","topic":"savunma, sanayi","year":"1926","text":"Kayseri’de TOMTAŞ ortaklığıyla uçak üretim tesisi kuruldu; fabrika 1926’da açıldı. İlk dönem havacılık sanayisi girişimi teknik ve finansal güçlüklerle karşılaştı.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Nuri Demirağ’ın uçak girişimleri","topic":"sanayi, havacılık","year":"1930’lar","text":"Nuri Demirağ özel girişim olarak uçak üretimi ve uçuş okulu projeleri geliştirdi. Bu çabalar devletin sanayi politikası kadar özel girişim tarihinin de parçasıdır.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://ataturkansiklopedisi.gov.tr/"},{"title":"İş Bankasının kuruluşu","topic":"ekonomi, kurumlar","year":"1924","text":"Türkiye İş Bankası 1924’te kuruldu. Ulusal bankacılık ve özel girişimin finansmanı, Cumhuriyet döneminin ekonomi politikası tartışmalarında önemli yer tuttu.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Sümerbankın kuruluşu","topic":"ekonomi, kurumlar","year":"1933","text":"Sümerbank, devlet sanayi işletmelerini yönetmek ve yeni yatırımları geliştirmek amacıyla kuruldu. Tekstil sanayisi kurumun temel faaliyet alanlarından biriydi.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://ataturkansiklopedisi.gov.tr/"},{"title":"Etibankın kuruluşu","topic":"ekonomi, kurumlar","year":"1935","text":"Etibank, maden kaynaklarını işletmek ve enerji alanında yatırım yapmak üzere kuruldu. Kurum, devlet öncülüğündeki sanayileşmenin parçalarındandı.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Maden Tetkik ve Arama Enstitüsü","topic":"bilim, ekonomi","year":"1935","text":"Maden Tetkik ve Arama Enstitüsü, Türkiye’nin yer altı kaynaklarını bilimsel yöntemlerle araştırmak üzere kuruldu. Kurum günümüzde MTA adıyla bilinir.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Elektrik ve enerji yatırımları","topic":"ekonomi, teknoloji","year":"1930’lar","text":"Sanayileşme hedefleri doğrultusunda elektrik üretimi ve enerji altyapısının geliştirilmesi gündeme geldi. Enerji yatırımları fabrikaların üretim kapasitesiyle bağlantılıydı.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"İzmir Enternasyonal Fuarı’nın kökeni","topic":"ekonomi, kültür","year":"1923–1930","text":"İzmir’de 1923 İktisat Kongresi kapsamında bir yerli ürünler sergisi düzenlendi. Bu etkinlik, daha sonra gelişen İzmir Fuarı geleneğinin başlangıçlarından sayılır.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://ataturkansiklopedisi.gov.tr/detay/1775/Atat%C3%BCrk-D%C3%B6nemi-Sanayi-Sergileri"},{"title":"1930 belediye seçimleri","topic":"siyaset, seçim","year":"1930","text":"Türkiye’de çok partili yerel seçim deneyimi 1930 belediye seçimleriyle yaşandı. Serbest Cumhuriyet Fırkası kısa süreli olarak bu seçimlere katıldı.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Terakkiperver Cumhuriyet Fırkası","topic":"siyaset, partiler","year":"1924–1925","text":"Terakkiperver Cumhuriyet Fırkası, Cumhuriyet döneminin ilk muhalefet partisi olarak 1924’te kuruldu ve 1925’te kapatıldı. Dönem, erken çok partili siyaset denemeleri açısından önemlidir.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://ataturkansiklopedisi.gov.tr/"},{"title":"Çok partili hayata geçiş denemeleri","topic":"siyaset, tarih","year":"1924 ve 1930","text":"Erken Cumhuriyet döneminde iki muhalefet partisi denemesi kısa süreli oldu. Bu deneyimler, dönemin siyasal rekabet koşulları ve güvenlik kaygılarıyla birlikte değerlendirilmelidir.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://ataturkansiklopedisi.gov.tr/"},{"title":"Takvim ve saat düzenlemesi","topic":"toplum, hukuk","year":"1925–1926","text":"Miladi takvim ve uluslararası saat düzeni kabul edildi. Uygulama, resmî işlemlerde ve uluslararası ilişkilerde ortak zaman ölçülerini kullanmayı sağladı.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Uluslararası rakamlar","topic":"eğitim, toplum","year":"1928","text":"Uluslararası rakamların kabulü, resmî yazışma, eğitim ve ticarette kullanılan sayı biçimini değiştirdi. Yeni rakamlar yeni harflerle aynı dönemde yaygınlaştı.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Ağırlık ve uzunluk ölçüleri","topic":"hukuk, ekonomi","year":"1931","text":"Ölçüler Kanunu ile metre ve kilogram temelli ölçü sistemi kabul edildi. Eski yerel ölçülerin yerine standart ölçüler getirildi.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Soyadı Kanunu ve Atatürk soyadı","topic":"hukuk, yaşam","year":"1934","text":"TBMM, Mustafa Kemal’e Atatürk soyadını verdi. Kanun, bu soyadının başka kişilerce kullanılmasını yasakladı.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"1934 tarihli Türk Kadınlar Birliği","topic":"kadın hakları, toplum","year":"1935","text":"Türk Kadınlar Birliği, kadınların siyasal hakları tanındıktan sonra 1935’te faaliyetini sonlandırdı. Kadın hareketinin Cumhuriyet dönemindeki örgütlü geçmişi daha eskidir.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://ataturkansiklopedisi.gov.tr/"},{"title":"Çocuk bayramı ve TBMM","topic":"çocuk, bayram","year":"1929","text":"23 Nisan, 1929’dan itibaren çocuklara armağan edilen bayram olarak kutlanmaya başladı. Bayram, TBMM’nin açılış yıldönümüyle çocuk temasını bir araya getirdi.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Gençlik ve Spor Bayramı","topic":"bayram, gençlik","year":"1938","text":"19 Mayıs’ın Gençlik ve Spor Bayramı olarak kutlanmasına ilişkin kanun 1938’de kabul edildi. Bayram, Samsun’a çıkış tarihini gençlik ve sporla ilişkilendirdi.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Cumhuriyet Bayramı","topic":"bayram, cumhuriyet","year":"1925","text":"29 Ekim’in millî bayram olarak kutlanmasını düzenleyen kanun 1925’te kabul edildi. Cumhuriyetin ilanı, her yıl resmî törenlerle anılmaya başladı.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Zafer Bayramı","topic":"bayram, askerlik","year":"1926","text":"30 Ağustos’un Zafer Bayramı olarak kutlanmasına ilişkin düzenleme 1926’da yapıldı. Bayram, 1922’deki Başkomutanlık Meydan Muharebesi’ni anar.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Anıtkabir’in inşası","topic":"anma, mimari","year":"1944–1953","text":"Anıtkabir’in inşası 1944’te başladı ve 1953’te tamamlandı. Atatürk’ün naaşı 10 Kasım 1953’te Anıtkabir’e nakledildi.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Atatürk Orman Çiftliği","topic":"tarım, yaşam","year":"1925","text":"Atatürk Orman Çiftliği Ankara’da tarım, hayvancılık ve modern üretim yöntemlerini denemek amacıyla kuruldu. Çiftlik daha sonra kamuya bağışlandı.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Yalova Termal ve modern tarım","topic":"tarım, yaşam","year":"1920’ler","text":"Yalova’daki arazi ve çiftlik düzenlemeleri tarımsal üretim ve dinlenme alanlarını bir arada içeriyordu. Atatürk’ün çiftlik girişimleri, örnek üretim ve modern tarım tartışmalarında anılır.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Florya Deniz Köşkü","topic":"mimari, yaşam","year":"1935","text":"Florya Deniz Köşkü 1935’te Atatürk’ün kullanımı için İstanbul kıyısında inşa edildi. Yapı, dönemin modern mimari örnekleri arasında gösterilir.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://ataturkansiklopedisi.gov.tr/"},{"title":"Ankara Palas","topic":"mimari, diplomasi","year":"1927","text":"Ankara Palas, başkent Ankara’da yabancı temsilcileri ve resmî konukları ağırlamak amacıyla açıldı. Yeni başkentin diplomatik ve toplumsal yaşamında rol oynadı.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Cumhuriyet mimarisi ve başkent planlaması","topic":"şehircilik, mimari","year":"1920–1930’lar","text":"Ankara’nın başkent olarak büyümesi yeni kamu yapıları, konutlar ve şehir planlaması gerektirdi. Erken Cumhuriyet mimarisi farklı yerli ve yabancı mimarların katkılarıyla gelişti.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://ataturkansiklopedisi.gov.tr/"},{"title":"Opera ve müzik politikası","topic":"kültür, sanat","year":"1930’lar","text":"Cumhuriyet yönetimi müzik eğitimi, konservatuvar ve sahne sanatları kurumlarını geliştirdi. 1934’te Özsoy operasının sahnelenmesi bu kültür politikasının örneklerindendir.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://ataturkansiklopedisi.gov.tr/"},{"title":"Özsoy Operası","topic":"kültür, diplomasi","year":"1934","text":"Adnan Saygun’un bestelediği ve Münir Hayri Egeli’nin metnini yazdığı Özsoy Operası, İran Şahı Rıza Pehlevi’nin ziyareti sırasında Ankara’da sahnelendi.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://ataturkansiklopedisi.gov.tr/"},{"title":"Türk musikisi ve konservatuvar çalışmaları","topic":"kültür, eğitim","year":"1930’lar","text":"Müzik eğitiminin kurumsallaşması için konservatuvarlar ve araştırma birimleri geliştirildi. Türk musikisi ile Batı müziğinin eğitimdeki yeri dönemin tartışma konularındandı.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://ataturkansiklopedisi.gov.tr/"},{"title":"Halkevlerinin kültür şubeleri","topic":"kültür, eğitim","year":"1932 sonrası","text":"Halkevleri dil-edebiyat, temsil, spor ve güzel sanatlar gibi şubelerle kültürel faaliyet yürüttü. Kurumlar şehirlerde ve ilçelerde eğitim etkinlikleri düzenledi.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Spor ve beden eğitimi","topic":"spor, eğitim","year":"1920–1930’lar","text":"Beden eğitimi ve spor, okul eğitimi ve gençlik politikalarının parçası olarak desteklendi. Kulüpler ve ulusal spor teşkilatları Cumhuriyet döneminde örgütlendi.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://ataturkansiklopedisi.gov.tr/"},{"title":"Türkiye’nin Milletler Cemiyetine üyeliği","topic":"dış politika, kurumlar","year":"1932","text":"Türkiye, Milletler Cemiyetine 1932’de üye oldu. Üyelik, Cumhuriyet’in uluslararası kuruluşlarla ilişkilerini genişletti.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Türkiye ve Sovyetler Birliği ilişkileri","topic":"dış politika, diplomasi","year":"1920–1930’lar","text":"TBMM Hükûmeti ile Sovyet Rusya Millî Mücadele yıllarında diplomatik ve mali ilişkiler kurdu. Cumhuriyet döneminde de iki ülke arasında dostluk ve iş birliği antlaşmaları yapıldı.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Türkiye-İran ilişkileri","topic":"dış politika, diplomasi","year":"1930’lar","text":"Türkiye ile İran arasında sınır ve güvenlik konularında iş birliği geliştirildi. Sadabat Paktı, iki ülkeyi Afganistan ve Irak’la birlikte bölgesel bir anlaşmada buluşturdu.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Türkiye-Irak ilişkileri","topic":"dış politika, diplomasi","year":"1930’lar","text":"Irak ile ilişkiler Musul sorununun çözümü ve bölgesel güvenlik konularını içerdi. Türkiye, Irak’la birlikte 1937 Sadabat Paktı’nı imzaladı.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Türkiye-Fransa ilişkileri","topic":"dış politika, diplomasi","year":"1921–1930’lar","text":"Ankara Antlaşması güney cephesindeki çatışmayı sona erdirdi. Sonraki dönemde Türkiye ile Fransa arasında Hatay meselesi ve Avrupa diplomasisi gündemde kaldı.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Türkiye-İngiltere ilişkileri","topic":"dış politika, diplomasi","year":"1920–1930’lar","text":"İngiltere ile ilişkiler Lozan, Musul, Boğazlar ve bölgesel güvenlik konularıyla şekillendi. Musul 1926’da, Boğazlar rejimi ise 1936’da yeni anlaşmalarla düzenlendi.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Boğazlar rejiminin Lozan düzenlemesi","topic":"dış politika, hukuk","year":"1923","text":"Lozan Boğazlar Sözleşmesi, Boğazlarda geçiş ve askerî statüye sınırlamalar getirdi. Türkiye 1936 Montrö Konferansı’nda bu rejimin değiştirilmesini talep etti.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://ataturkansiklopedisi.gov.tr/detay/355/Montreux_%28Montr%C3%B6%29_Bo%C4%9Fazlar_S%C3%B6zle%C5%9Fmesi_%2822_Haziran-20_Temmuz_1936%29"},{"title":"Montreux Konferansı","topic":"dış politika, diplomasi","year":"22 Haziran–20 Temmuz 1936","text":"Montreux Konferansı İsviçre’de toplandı ve Boğazlardan geçiş rejimini yeniden ele aldı. Sözleşme 20 Temmuz 1936’da imzalandı.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://ataturkansiklopedisi.gov.tr/detay/355/Montreux_%28Montr%C3%B6%29_Bo%C4%9Fazlar_S%C3%B6zle%C5%9Fmesi_%2822_Haziran-20_Temmuz_1936%29"},{"title":"Hatay Devleti","topic":"dış politika, tarih","year":"2 Eylül 1938","text":"Hatay Devleti 2 Eylül 1938’de kuruldu. Atatürk’ün ölümünden sonra, 1939’da Hatay Meclisinin kararıyla Türkiye’ye katıldı.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://ataturkansiklopedisi.gov.tr/detay/907/Atat%C3%BCrk-D%C3%B6nemi-T%C3%BCrkiye-Orta-Do%C4%9Fu-%C4%B0li%C5%9Fkileri"},{"title":"Balkan Antantı’nın sınırlılıkları","topic":"dış politika, tarih","year":"1934–1941","text":"Balkan Antantı bölgesel iş birliği sağlasa da ortak savunmayı zorunlu kılan güçlü bir mekanizma kurmadı. Avrupa’daki güç dengeleri değişince antantın etkisi zayıfladı.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://ataturkansiklopedisi.gov.tr/detay/682/Balkan-Antant%C4%B1"},{"title":"Nöbet defterleri ve günlük yaşam kaynakları","topic":"kaynaklar, yaşam","year":"1931–1938","text":"Cumhurbaşkanlığı nöbetçi yaverlerinin defterleri Atatürk’ün günlük programını saat saat kaydetti. Bu kayıtlar, biyografik kronolojiyi belgelemek için kullanılan kaynaklardandır.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Atatürk kronolojisinin kaynak çeşitliliği","topic":"kaynaklar, tarih","year":"1881–1938","text":"ATAM’ın kaynakçalı Atatürk günlüğü anı, söylev, telgraf, TBMM tutanağı, gazete ve arşiv belgelerini birlikte inceler. Bazı olay tarihlerindeki kaynak farklılıkları ayrıca gösterilir.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Nutuk’un zaman aralığı","topic":"eserler, Millî Mücadele","year":"1919–1927","text":"Nutuk, 1919’da Samsun’a çıkıştan başlayarak 1927’ye uzanan dönemi ele alır. Eser, tarihsel olayları Atatürk’ün geriye dönük anlatımı ve belgeleriyle sunar.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/mustafa-kemal-ataturk-tarafindan-kaleme-alinan-nutuk-ozgun-diliyle-yayinda/"},{"title":"Nutuk’un seslendiriliş süresi","topic":"eserler, konuşma","year":"15–20 Ekim 1927","text":"Nutuk’un okunması altı güne yayıldı ve Cumhuriyet Halk Partisi İkinci Kurultayı’nda gerçekleşti. Bu bilgi, ATAM’ın Nutuk yayın duyurusunda da belirtilir.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/mustafa-kemal-ataturk-tarafindan-kaleme-alinan-nutuk-ozgun-diliyle-yayinda/"},{"title":"Atatürk’ün el yazısı notları","topic":"eserler, kaynaklar","year":"yaşamı boyunca","text":"Atatürk’ün not defterleri, karalama ve kitap kenarı notları düşünce ve çalışma süreçlerine ilişkin birincil kaynaklardır. Bir notu yorumlarken tarih, belge bütünlüğü ve bağlam araştırılmalıdır.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"},{"title":"Tarihî alıntı doğrulama yöntemi","topic":"kaynaklar, yöntem","year":"araştırma ilkesi","text":"Bir sözün Atatürk’e ait sayılması için güvenilir birincil belgeye, tarih ve bağlama bakılmalıdır. İnternette çok tekrarlanması tek başına kaynak kanıtı değildir.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/kitaplar/ataturkun-soylev-ve-demecleri-i-iii/"},{"title":"Tarihsel kararları bugüne aktarma sınırı","topic":"yöntem, günümüz","year":"yöntem","text":"Geçmişteki bir ilkeyi güncel soruna uygularken dönem koşulları ile bugünün verileri ayrılmalıdır. Tarihsel kaynaklar doğrudan güncel politika talimatı yerine bağlam ve karşılaştırma sağlar.","source":"Atatürk Ansiklopedisi / Atatürk Araştırma Merkezi (ATAM)","url":"https://atam.gov.tr/dogumundan-olumune-kadar-kaynakcali-ataturk-gunlugu-tekrar-yayinda/"}];
